// Chikiting System - decides whether this request is worth a cloud call,
// before any catalogue wording is applied.
//
// A catalogue hit is already the approved wording, so re-running it through a
// bigger model could only drift it. Only unmatched requests that landed in
// Mid- or Large-Scale are worth escalating - and only when the app told us a
// cloud model is actually configured (allow_escalation), so a missing API key
// can never send the run down a branch that has to fail.

const CATALOG_KEYS = [
  'ADVERTISING_MATERIALS_REVIEW', 'WEBSITE_AUDIT', 'THIRD_PARTY_ONBOARDING',
  'COMPLIANCE_REVIEW', 'REPORT_DATA_COMPLETION', 'DATA_VALIDATION',
  'TRAINING_SUMMARY', 'TRAINING_LODGEMENT', 'MONITORING_ASSURANCE_AUDIT',
  'IT_EQUIPMENT', 'LOGIN_LOGOUT'
];

const VALID_CATEGORIES = [
  'Common Request', 'Special Request', 'Small-Scale Request',
  'Mid-Scale Request', 'Large-Scale Request'
];

const CATEGORY_ALIASES = {
  'large request': 'Large-Scale Request',
  'large-scale': 'Large-Scale Request',
  'mid request': 'Mid-Scale Request',
  'medium request': 'Mid-Scale Request',
  'mid-scale': 'Mid-Scale Request',
  'small request': 'Small-Scale Request',
  'small-scale': 'Small-Scale Request',
  'common': 'Common Request',
  'special': 'Special Request'
};

const ESCALATE_CATEGORIES = ['Mid-Scale Request', 'Large-Scale Request'];

const body = $('Webhook').first().json.body || {};
const cloudAvailable = String(body.allow_escalation || 'No') === 'Yes';

const results = [];
for (const item of $input.all()) {
  // An extraction that failed outright arrives with no output object at all -
  // it stays local and is flagged for review downstream.
  const ai = item.json.output || {};
  const key = String(ai.request_type || 'OTHER').trim().toUpperCase();
  const raw = String(ai.category || '').trim();
  const category = VALID_CATEGORIES.includes(raw)
    ? raw
    : (CATEGORY_ALIASES[raw.toLowerCase()] || 'Common Request');

  const escalate = cloudAvailable
    && !CATALOG_KEYS.includes(key)
    && ESCALATE_CATEGORIES.includes(category);

  results.push({ json: { ...item.json, output: { ...ai, should_escalate: escalate ? 'Yes' : 'No' } } });
}
return results;

