// Chikiting System - overlays the approved catalogue wording, verbatim, and
// writes the first thing the requester reads back on their ticket.
//
// This workflow only classifies and drafts. CodeIgniter persists the result,
// so there is one writer and one source of truth.
//
// Exactly one branch reaches here per request - local or escalated - so this
// runs once either way.

const CATALOG = {
  ADVERTISING_MATERIALS_REVIEW: {
    request_title: 'Advertising Materials Review Request',
    category: 'Common Request',
    responsible_department: 'Compliance HQ',
    description: 'Marketing Team needed compliance team approval of all advertising materials that the company will be using',
    expected_deliverable: 'Compliance team approved the advertising materials.',
    suggested_tat: 'Depends on the complexity and depth of the inquiry',
    requirements_needed: 'Advertising materials, Manager Approval, Marketing Team revision (if applicable)',
    closure_criteria: 'Marketing Team received the approved advertising materials',
    priority: 'Medium' },
  WEBSITE_AUDIT: {
    request_title: 'Website Audit Request',
    category: 'Large-Scale Request',
    responsible_department: 'Compliance HQ',
    description: "Website Team needed compliance approval when they make changes in the website specially if it's critical information",
    expected_deliverable: 'Compliance team approved the new website webpage or website revision.',
    suggested_tat: 'Depends on the complexity and depth of the inquiry',
    requirements_needed: 'Advertising materials, Manager Approval, Website Team revision (if applicable)',
    closure_criteria: 'Website Team received the approval of such changes in website',
    priority: 'High' },
  THIRD_PARTY_ONBOARDING: {
    request_title: 'Third Party Onboarding',
    category: 'Common Request',
    responsible_department: 'Compliance HQ',
    description: 'Sales team request onboarding of third parties',
    expected_deliverable: 'Third party agreement is fully signed and welcome email has been sent.',
    suggested_tat: '1-2 weeks depends on the complexity and/or volume',
    requirements_needed: 'Third party information, Compliance Manager Approval, Sales Manager Approval, Chief Revenue Officer Approval, Third Party Director contract signing, Chief Revenue Officer contract signing, informing Help Desk for Creation of Account, informing Accounting for Comission Fee and Sales Manager to confirm third party to have onboarding training',
    closure_criteria: 'Third party agreement is fully signed and welcome email has been sent.',
    priority: 'High' },
  COMPLIANCE_REVIEW: {
    request_title: 'Review Request for Compliance',
    category: 'Special Request',
    responsible_department: 'Compliance HQ',
    description: 'Any team will request a review of current regulatory updates in regards with their processes and/or policy',
    expected_deliverable: 'Compliance will answer the question with basis',
    suggested_tat: 'Depends on the complexity and depth of the inquiry',
    requirements_needed: 'Details of the request or inquiry',
    closure_criteria: 'Inquiry answered or comments given by Compliance Team',
    priority: 'Medium' },
  REPORT_DATA_COMPLETION: {
    request_title: 'Request for Report Data Completion',
    category: 'Large-Scale Request',
    responsible_department: 'Operations Team and Support Team',
    description: 'Request for data completion for Regulatory Report',
    expected_deliverable: 'Indicator Owner/Data Collection Owner provided the complete data requested',
    suggested_tat: '5 Working Days',
    requirements_needed: 'All required data listed in the Regulatory Report',
    closure_criteria: 'Data Completion requested is completed',
    priority: 'High' },
  DATA_VALIDATION: {
    request_title: 'Request for Data Validation',
    category: 'Large-Scale Request',
    responsible_department: 'Operations Team and Support Team',
    description: 'Request for data validation for Regulatory Report',
    expected_deliverable: 'Indicator Owner/Data Responsible Person provided data validation (including comments) requested',
    suggested_tat: '2 Working Days',
    requirements_needed: 'Depends on the data being validated',
    closure_criteria: 'Data Validation requested is completed',
    priority: 'High' },
  TRAINING_SUMMARY: {
    request_title: 'Summary of Training Request',
    category: 'Common Request',
    responsible_department: 'TQA Team',
    description: 'Request of Summary of Training to TQA Team',
    expected_deliverable: 'TQA Team to provide the requested Training Summary',
    suggested_tat: '2 Days',
    requirements_needed: 'Summary of Training in a given period',
    closure_criteria: 'Summary of Training is provided',
    priority: 'Medium' },
  TRAINING_LODGEMENT: {
    request_title: 'Request to lodge a Training',
    category: 'Common Request',
    responsible_department: 'TQA Team',
    description: 'Request to lodge a Training in the Training Register - Knowledge Base',
    expected_deliverable: 'TQA Team to lodge the requested Training in the Training Register - Knowledge Base',
    suggested_tat: '1 Day',
    requirements_needed: 'Training Date and hour, Training Description, Trainee name',
    closure_criteria: 'Training is logged in the Training Register',
    priority: 'Medium' },
  MONITORING_ASSURANCE_AUDIT: {
    request_title: 'Compliance Monitoring Assurance Program',
    category: 'Large-Scale Request',
    responsible_department: 'AU Operation Team',
    description: 'Internal Audit every quarter of different team',
    expected_deliverable: 'Audit Report has been approved by CRC',
    suggested_tat: 'Every 3 months',
    requirements_needed: 'Management Review Form, Updated policy or processes if applicable, audit report',
    closure_criteria: 'Audit report has been finalized',
    priority: 'High' },
  IT_EQUIPMENT: {
    request_title: 'IT equipment',
    category: 'Special Request',
    responsible_department: 'IT Team',
    description: 'Equipment replacement or trouble shooting',
    expected_deliverable: 'IT team replaced or fix IT equipment',
    suggested_tat: '1 day',
    requirements_needed: 'IT equipment',
    closure_criteria: 'Fully functional IT Equipment',
    priority: 'High' },
  LOGIN_LOGOUT: {
    request_title: 'Log-in / Log - out Request',
    category: 'Special Request',
    responsible_department: 'HR / IT',
    description: 'Cannot log in or log out / Log in log out do not reflect in HRIS',
    expected_deliverable: 'HR will provide Log in/ log out time. IT will update log in log out time in HRIS',
    suggested_tat: '1 day',
    requirements_needed: 'Log in time guard slip',
    closure_criteria: 'Log in Log out time has been revised',
    priority: 'High' }
};

// The categories the app accepts. Anything else is coerced below so a model
// slip cannot land an unfilterable value in the tickets table.
const VALID_CATEGORIES = [
  'Common Request', 'Special Request', 'Small-Scale Request',
  'Mid-Scale Request', 'Large-Scale Request'
];

// Older prompt wording and common model slips, mapped onto the real options.
const CATEGORY_ALIASES = {
  'large request': 'Large-Scale Request',
  'large-scale': 'Large-Scale Request',
  'mid request': 'Mid-Scale Request',
  'medium request': 'Mid-Scale Request',
  'mid-scale': 'Mid-Scale Request',
  'small request': 'Small-Scale Request',
  'small-scale': 'Small-Scale Request',
  'common': 'Common Request',
  'special': 'Special Request'
};

const DAYS = { '1 day': 1, '1 Day': 1, '1 business day': 1, '2 Days': 2, '2 Working Days': 2,
               '1-2 business days': 2, '5 Working Days': 5 };

const addWorkingDays = (n) => {
  const d = new Date();
  let added = 0;
  while (added < n) { d.setDate(d.getDate() + 1); const w = d.getDay(); if (w !== 0 && w !== 6) added++; }
  return d.toISOString().slice(0, 10);
};

const normaliseCategory = (raw) => {
  const value = String(raw || '').trim();
  if (VALID_CATEGORIES.includes(value)) return value;
  return CATEGORY_ALIASES[value.toLowerCase()] || null;
};

// The only teams a ticket may be routed to. A small model asked for one of
// eleven names will occasionally answer with something reasonable-sounding and
// not on the list - 'Not Applicable', 'General Support'. Left alone that lands
// the ticket in a department no agent account can hold, which is worse than a
// wrong department: it is a queue nobody is watching and nothing looks broken.
const VALID_DEPARTMENTS = [
  'Compliance HQ', 'Operations Team and Support Team', 'TQA Team',
  'AU Operation Team', 'IT Team', 'HR / IT', 'Reports/WFM',
  'Technical - Web', 'Technical - Marketing', 'Technical - Salesforce/Tally',
  'Technical - SQL'
];

// Falls back to the department the requester picked at submission - which came
// from a fixed dropdown, so it is always routable - and flags the ticket.
const normaliseDepartment = (raw, fallback) => {
  const value = String(raw || '').trim();
  if (VALID_DEPARTMENTS.includes(value)) return { department: value, ok: true };

  const hit = VALID_DEPARTMENTS.find((d) => d.toLowerCase() === value.toLowerCase());
  if (hit) return { department: hit, ok: true };

  return { department: String(fallback || '').trim() || 'IT Team', ok: false };
};

// The opening message of the ticket's chat thread. The model drafts the human
// part; the facts around it are assembled here so they always match the row
// that was actually saved, and so a dead model still gets a straight answer.
const CONFIDENCE = ['low', 'medium', 'high'];

// A model that ignored the field, or invented a fourth level, is read as
// 'medium' - the level that never on its own unlocks a suggestion.
const normaliseConfidence = (raw) => {
  const value = String(raw || '').trim().toLowerCase();
  return CONFIDENCE.includes(value) ? value : 'medium';
};

const opening = (out, ai, modelOk) => {
  if (!modelOk) {
    return [
      'Thanks - your ticket is saved and nothing has been lost.',
      'I could not reach my classifier just now, so the details below have not been filled in yet. On a first run that usually means the local model is still downloading. Either way a person will review this.',
      'Reply here if there is anything you want to add.'
    ].join('\n\n');
  }

  const dept = String(out.responsible_department || '').trim() || 'the assigned team';
  const parts = [];

  const drafted = String(ai.requester_message || '').trim();
  parts.push(drafted || `Thanks - I have logged this as "${out.request_title}" and routed it to ${dept}.`);

  const facts = [];
  if (out.expected_deliverable) facts.push(`Done looks like: ${out.expected_deliverable}`);
  if (out.suggested_tat) facts.push(`Turnaround: ${out.suggested_tat}`);
  if (out.requirements_needed) facts.push(`To start, we need: ${out.requirements_needed}`);
  if (facts.length) parts.push(facts.join('\n'));

  // The gate. Steps are only ever presented as steps when the model said the
  // request is self-serviceable AND said it was sure. Everything else gets an
  // acknowledgement, which is honest and still routes the ticket. PHP applies
  // the same rule again before the message is stored - see TicketAssistant.
  if (out.suggesting === 'Yes') {
    parts.push(out.matched_prior
      ? 'That is what resolved it last time this came up. If it works for you too, reply "resolved" here and I will update the ticket.'
      : 'If you try that and it sorts itself out, reply "resolved" here and I will update the ticket for you.');
  } else {
    parts.push(`I have not tried to solve this one myself - ${dept} owns the next step. Reply here with anything that changes and I will keep the ticket up to date.`);
  }

  return parts.join('\n\n');
};

const submitted = $('Webhook').first().json.body || {};

const results = [];
for (const item of $input.all()) {
  const ai = item.json.output || {};
  // No output object at all means the extraction never ran (model cold, down,
  // or refused). The ticket is still saved - flagged for a human.
  const modelOk = Object.keys(ai).length > 0;

  const key = String(ai.request_type || 'OTHER').trim().toUpperCase();
  const row = CATALOG[key];
  const out = row ? { ...ai, ...row } : { ...ai };

  out.matched_catalogue_key = row ? key : 'OTHER';
  out.needs_human_review = (row && modelOk) ? 'No' : 'Yes';

  // Category drives both the dashboard filters and the escalation gate, so an
  // off-list value has to be coerced rather than passed through.
  const category = normaliseCategory(out.category);
  if (category === null) {
    out.needs_human_review = 'Yes';
    out.category_raw = out.category || '';
    out.category = 'Common Request';
  } else {
    out.category = category;
  }

  // Same treatment as category, and for the same reason: this one decides who
  // can see the ticket at all, so an off-list value has to be coerced rather
  // than passed through.
  out.responsible_department = String(submitted['Submitting Department'] || '').trim();
  out.model_department = String(ai.responsible_department || '').trim();

  if (!out.requirements_needed || !String(out.requirements_needed).trim()) {
    out.requirements_needed = 'To be confirmed with the requester - not provided in the request';
  }
  if (!out.request_title || !String(out.request_title).trim()) {
    out.request_title = 'Unclassified Request';
  }
  if (!out.priority) out.priority = out.category === 'Large-Scale Request' ? 'High' : 'Medium';
  out.due_date = DAYS[out.suggested_tat] ? addWorkingDays(DAYS[out.suggested_tat]) : '';

  out.self_service = String(ai.self_service || '').trim().toLowerCase().startsWith('y') ? 'Yes' : 'No';
  out.confidence = normaliseConfidence(ai.confidence);
  out.model_ok = modelOk ? 'Yes' : 'No';
  out.should_escalate = out.should_escalate || 'No';

  // Whether this ticket gets advice or an acknowledgement.
  //
  // Two doors, and nothing else opens one:
  //
  //   (a) trivially self-serviceable, and the model is sure it is
  //   (b) this helpdesk has resolved the same thing before, and the model
  //       pointed at which case - so the advice is a person's answer being
  //       repeated, not the model's opinion being invented
  //
  // The prior case is only honoured if it actually exists in what we sent.
  // A model that returns "1" when no cases were supplied is hallucinating a
  // memory, and that is the exact failure this whole mechanism exists to stop.
  const priorSupplied = String(submitted.prior_context || '').trim() !== '';
  const priorCase = String(ai.matched_prior || '').trim();
  const usedPrior = priorSupplied && /^[1-9]$/.test(priorCase)
    && submitted.prior_context.includes('CASE ' + priorCase + ' ');

  out.matched_prior = usedPrior ? priorCase : '';

  const trivial = out.self_service === 'Yes' && out.confidence === 'high';

  out.suggesting = (out.needs_human_review === 'No' && (trivial || usedPrior)) ? 'Yes' : 'No';

  out.requester_message = opening(out, ai, modelOk);

  results.push({ json: { ...item.json, output: out } });
}
return results;
